-- =========================================
-- SHOPKART - SQL BUSINESS ANALYSIS
-- =========================================

-- BASIC LEVEL  -- 

-- 1. What is the total number of customers, products, orders and categories?

SELECT
    (SELECT COUNT(*) FROM customers) AS total_customers,
    (SELECT COUNT(*) FROM products) AS total_products,
    (SELECT COUNT(*) FROM orders) AS total_orders,
    (SELECT COUNT(*) FROM category) AS total_categories;
    
-- 2. What is the total revenue generated by ShopKart?

SELECT
SUM(total_amount) AS total_revenue
FROM payments
WHERE payment_status = 'Completed';

-- 3. What is the total number of orders by order status?

SELECT 
    order_status, COUNT(*) AS total_orders
FROM
    orders
GROUP BY order_status
ORDER BY total_orders DESC;

-- 4. Which are the top 10 products by selling price?

SELECT
*
FROM products
ORDER BY price DESC
LIMIT 10;

-- 5. Which product categories have the highest number of products?

SELECT 
	c.category_name,
	c.Category_id,
	count(p.product_id) as total_products
FROM category c
LEFT JOIN products p 
	ON p.Category_ID = c.Category_id
GROUP BY 
	c.category_name,
	c.Category_id
ORDER BY total_products DESC ; 

-- 6. Which payment methods are used most frequently?

SELECT 
    payment_method, COUNT(order_id) AS total_payments
FROM
    payments
GROUP BY payment_method
ORDER BY total_payments DESC;

-- 7. Which cities and states generate the most orders?

SELECT 
    c.city, c.state, COUNT(o.order_id) AS total_orders
FROM
    customers c
        LEFT JOIN
    orders o ON c.customer_id = o.customer_id
GROUP BY c.city , c.state
ORDER BY total_orders DESC;

-- 8. What is the current stock level of each product, and which products have low stock?

SELECT 
product_id,
product_name,
stock,
CASE WHEN stock > 1000 THEN 'high'
	WHEN stock BETWEEN 200 and 1000 THEN 'medium'
    ELSE 'low'
    END AS stock_segments
FROM products
ORDER BY stock ASC;

-- Concept covered: SELECT, WHERE, ORDER BY, GROUP BY, COUNT(), SUM(), LIMIT.


-- INTERMEDIATE LEVEL --

-- 9. What is the monthly revenue trend, and which month generated the highest revenue? 

WITH monthly_trend AS 
(
    SELECT 
        DATE_FORMAT(o.order_date, '%Y-%m') AS order_month,
        SUM(p.total_amount) AS total_sales
    FROM orders o 
    LEFT JOIN payments p 
        ON p.order_id = o.order_id
    GROUP BY order_month
),
revenue_ranking AS
(
    SELECT 
        order_month,
        total_sales,
        DENSE_RANK() OVER (ORDER BY total_sales DESC) AS revenue_rank
    FROM monthly_trend
)
SELECT 
    order_month,
    total_sales,
    CASE
        WHEN revenue_rank = 1 THEN 'Highest Revenue Month'
        ELSE 'Other Month'
    END AS revenue_status
FROM revenue_ranking
ORDER BY order_month ASC;

-- 10. What percentage of total revenue does each product category contribute?

WITH category_revenue AS
(
SELECT
c.category_id,
c.category_name,
SUM(p.price * oi.quantity) AS category_sales
FROM category c
JOIN products p
ON c.category_id = p.category_id
JOIN order_items oi
ON p.product_id = oi.product_id
GROUP BY c.category_id, c.category_name
),
overall_revenue AS
(
SELECT SUM(category_sales) AS total_revenue
FROM category_revenue
)
SELECT
cr.category_id,
cr.category_name,
ROUND(cr.category_sales, 2) AS category_sales,
ROUND(orr.total_revenue, 2) AS total_revenue,
ROUND(
	cr.category_sales * 100.0 / NULLIF(orr.total_revenue, 0),
    2) AS percentage_revenue
FROM category_revenue cr
CROSS JOIN overall_revenue orr
ORDER BY cr.category_sales DESC;

-- 11. Who are the top 10 customers by total spending?

SELECT 
    c.customer_id,
    c.customer_name,
    SUM(p.total_amount) AS total_spending
FROM
    customers c
	JOIN orders o
    ON c.customer_id = o.customer_id
	JOIN payments p 
    ON p.order_id = o.order_id
GROUP BY c.customer_id , c.customer_name
ORDER BY total_spending DESC
LIMIT 10;

-- 12. Which products generate the highest revenue versus the highest sales quantity?

WITH total_revenue AS 
(
SELECT 
	p.product_name,
    p.product_id,
    sum(p.price*oi.quantity) AS highest_revenue,
    SUM(oi.quantity) AS total_quantity
FROM products p
LEFT JOIN order_items oi
	on Oi.product_id = p.product_id
GROUP BY 
	p.product_name,
    p.product_id
)
, highest_quantity AS
(
SELECT
	product_id,
    product_name,
    highest_revenue,
    total_quantity,
	dense_rank() over(order by total_quantity DESC ) as quantity_rank,
    dense_rank() over(order by highest_revenue DESC) AS revenue_rank
FROM total_revenue
)
SELECT 
	*
FROM highest_quantity 
WHERE revenue_rank = 1 
	or quantity_rank = 1
;
    
-- 13. What is the average order value (AOV), and how does it vary by month?

SELECT 
	date_format(order_date,'%Y-%m') AS months,
	COUNT(order_id) AS total_orders,
    SUM(order_total) AS total_revenue,
    ROUND(avg(order_total ),2) as avg_order_value 
from orders
WHERE order_status = 'Delivered'
GROUP BY months 
ORDER BY months asc;

-- 14. What percentage of customers have placed more than one order?

WITH total_customer_order AS 
(
SELECT 
c.customer_id,
c.customer_name,
COUNT(o.order_id) as total_order
FROM customers c
LEFT JOIN orders o
ON c.customer_id = o.customer_id
GROUP BY c.customer_id,
	c.customer_name
)
,repeat_customers as 
( 
SELECT 
count(*) as repeated_customers
FROM total_customer_order
WHERE total_order > 1
)
,total_customers as
(
SELECT 
count(*) as total_customers
FROM customers
)  
SELECT 
rc.repeated_customers,
tc.total_customers,
ROUND(rc.repeated_customers*100/tc.total_customers,
	2) as percentage
FROM total_customers tc
CROSS JOIN repeat_customers RC;

-- 15. Which payment methods have the highest cancellation,refund or return rates?

SELECT
p.payment_method,
COUNT(DISTINCT o.order_id) AS total_orders,
COUNT(DISTINCT CASE WHEN o.order_status IN ('Cancelled', 'Returned', 'Refunded')
	THEN o.order_id
    END) AS cancelled_refunded_orders,
ROUND(
	COUNT(DISTINCT CASE
    WHEN o.order_status IN ('Cancelled', 'Returned', 'Refunded')
    THEN o.order_id
    END) * 100.0 /
    NULLIF(COUNT(DISTINCT o.order_id), 0),
    2) AS cancellation_refund_rate
FROM payments p
JOIN orders o
    ON p.order_id = o.order_id
GROUP BY p.payment_method
ORDER BY cancellation_refund_rate DESC;

-- 16. Which states have the highest revenue but relatively low order volumes?

WITH state_revenue AS
(
SELECT 
	c.state,
	COUNT(DISTINCT o.order_id) AS total_orders,
    SUM(p.total_amount) AS total_revenue
FROM orders o
JOIN customers c
	ON o.customer_id = c.customer_id
JOIN payments p
    ON o.order_id = p.order_id
GROUP BY c.state
)
,state_analysis AS
(
SELECT
	state,
    total_orders,
    total_revenue,
    ROUND(AVG(total_orders) OVER(), 2) AS avg_orders
FROM state_revenue
)
,classification AS
(
SELECT
	state,
    total_orders,
    total_revenue,
    avg_orders,
CASE WHEN total_orders < avg_orders * 0.90
    THEN 'Low Volume'
    ELSE 'Normal/High Volume'
END AS order_volume_category
FROM state_analysis
)
SELECT
    state,
    total_orders,
    total_revenue,
    avg_orders,
    order_volume_category
FROM classification
ORDER BY total_revenue DESC;

-- 17. Which products have high stock but low sales?

WITH product_performance AS
(
SELECT
	p.product_id,
    p.product_name,
    p.stock AS current_stock,
    COALESCE(SUM(oi.quantity), 0) AS units_sold,
    COALESCE(SUM(oi.quantity * p.price), 0) AS total_sales
FROM products p
LEFT JOIN order_items oi
        ON p.product_id = oi.product_id
GROUP BY p.product_id,
    p.product_name,
    p.stock
)
,benchmarks AS
(
SELECT
	AVG(current_stock) AS avg_stock,
    AVG(units_sold) AS avg_units_sold
FROM product_performance
)
,classification AS
(
SELECT
	pp.product_id,
    pp.product_name,
    pp.current_stock,
    pp.units_sold,
    pp.total_sales,
    b.avg_stock,
    b.avg_units_sold,
CASE
	WHEN pp.current_stock > b.avg_stock
	AND pp.units_sold < b.avg_units_sold
	THEN 'High Stock - Low Sales'
	ELSE 'Normal Performance'
	END AS product_category
FROM product_performance pp
CROSS JOIN benchmarks b
)
SELECT *
FROM classification
WHERE product_category = 'High Stock - Low Sales'
ORDER BY current_stock DESC;

-- 18. How do product ratings compare with revenue and quantity sold?

WITH products_sales as
(
SELECT
p.Product_Name,
p.Rating as current_rate,
COALESCE(SUM(oi.quantity), 0) AS total_quantity,
COALESCE(SUM(p.price * oi.quantity), 0) AS total_sales
FROM products p
LEFT JOIN order_items oi
    ON p.product_id = oi.product_id
GROUP BY
p.product_id,
p.Product_Name,
p.rating
)
,avg_quantity as
(
SELECT 
*,
avg(total_quantity) OVER() as avg_quantity
FROM products_sales
)
,classification as
(
SELECT 
product_name,
current_rate,
total_sales,
total_quantity,
CASE WHEN current_rate IS NULL THEN 'Rating Not Available'
	WHEN current_rate >= 4 AND total_quantity >= avg_quantity
	THEN 'High Rating - High Sales'
	WHEN current_rate >= 4
	THEN 'High Rating - Low Sales'
	WHEN total_quantity >= avg_quantity
	THEN 'Low Rating - High Sales'
	ELSE 'Low Rating - Low Sales'
	END AS segments
    FROM avg_quantity
)
SELECT *
FROM classification
ORDER BY current_rate DESC;

-- Concepts covered: CTEs, JOINs (INNER, LEFT, CROSS), DENSE_RANK(), CASE WHEN, DATE_FORMAT(), ROUND(), 
-- NULLIF(), COALESCE(), aggregate functions, percentage calculations.
    
-- ADVANCED LEVEL -- 

-- 19. What is the cumulative revenue generated over time?

SELECT
    DATE_FORMAT(order_date, '%Y-%m') AS order_month,
    ROUND(SUM(order_total), 2) AS monthly_revenue,
    ROUND(
	SUM(SUM(order_total)) OVER ( ORDER BY DATE_FORMAT(order_date, '%Y-%m')),
	2) AS cumulative_revenue
FROM orders
WHERE order_status = 'Delivered'
GROUP BY order_month
ORDER BY order_month;

-- 20. What is the month-over-month revenue growth percentage?

WITH monthly_revenue AS 
(
SELECT 
date_format(order_date,'%Y-%m') AS order_month,
ROUND(sum(order_total),2) AS current_month_sales,
LAG(ROUND(sum(order_total),2)) OVER(order by date_format(order_date,'%Y-%m')) AS previous_month_sales
FROM orders
WHERE order_status = 'Delivered'
GROUP BY order_month
 )
 ,growth_percentage AS 
 (
 SELECT 
 order_month,
 current_month_sales,
 ROUND(
	((current_month_sales - previous_month_sales) / NULLIF(previous_month_sales,0)*100) 
    ,2) AS growth_percentage
 FROM monthly_revenue
 )
 SELECT *
 FROM growth_percentage
 ;
 
-- 21. Which are the top 3 products by revenue within each category?

WITH product_revenue as 
(
SELECT 
c.category_name,
p.product_name,
p.product_id,
sum(p.price*oi.quantity) as total_product_sales,
DENSE_RANK() OVER(
    PARTITION BY c.category_name
    ORDER BY sum(p.price*oi.quantity) DESC) as product_ranking
FROM products p
JOIN category c
	ON c.category_id = p.category_id
JOIN order_items oi
	ON p.product_id = oi.product_id
GROUP BY c.category_name,
	p.product_name,
	p.product_id
)
SELECT*
FROM product_revenue
WHERE product_ranking <= 3
ORDER BY category_name, 
	product_ranking;

-- 22. Which customers contribute the most to total revenue, and what is their percentage contribution?


WITH customer_revenue AS 
(
SELECT 
c.customer_id,
c.customer_name,
sum(o.order_total) AS total_sales
FROM customers c
LEFT JOIN orders o
ON c.customer_id = o.customer_id
AND o.order_status = 'Delivered'
GROUP BY c.customer_id,
	c.customer_name
 )
,revenue_contribution AS 
 (
SELECT 
customer_id,
customer_name,
total_sales,
ROUND(
	sum(total_sales) OVER(),2) AS total_revenue,
ROUND(
	(total_sales/ NULLIF(sum(total_sales) OVER(),0))*100
    ,2) AS percentage_contribution
FROM customer_revenue
)
SELECT *
FROM revenue_contribution
ORDER BY total_sales DESC;

-- 23. Which customers have not purchased recently and may be at risk of churn?

WITH customer_last_order AS
(
SELECT
c.customer_id,
c.customer_name,
MAX(o.order_date) AS last_order
FROM customers c
LEFT JOIN orders o
	ON c.customer_id = o.customer_id
GROUP BY c.customer_id, c.customer_name
),
analysis_date AS
(
SELECT MAX(order_date) AS reference_date
FROM orders
),
churn_analysis AS
(
SELECT
c.customer_id,
c.customer_name,
c.last_order,
a.reference_date,
DATEDIFF(a.reference_date, c.last_order) AS days_since_last_purchase,
CASE WHEN c.last_order IS NULL THEN 'Never Purchased'
	WHEN DATEDIFF(a.reference_date, c.last_order) <= 30 THEN 'Active'
	WHEN DATEDIFF(a.reference_date, c.last_order) <= 90 THEN 'At Risk'
	ELSE 'High Risk'
	END AS customer_status
FROM customer_last_order c
CROSS JOIN analysis_date a
)
SELECT *
FROM churn_analysis
ORDER BY days_since_last_purchase DESC;

-- 24. Segment customers into high-, medium- and low-value groups using spending and purchase frequency.

WITH customer_analysis AS 
(
SELECT 
c.customer_name,
c.customer_id,
count(o.order_id) as total_orders,
COALESCE(SUM(o.order_total), 0) as total_spending
FROM customers c
LEFT JOIN orders o 
	ON c.customer_id = o.customer_id
GROUP BY c.customer_name,
c.customer_id
) 
, customer_frequency_analysis AS
(
SELECT 
customer_id,
customer_name,
total_orders,
total_spending,
CASE WHEN total_orders >= 10 and total_spending >= 100000 THEN 'high'
	WHEN total_orders >= 5 and total_spending >= 50000 THEN 'medium'
    ELSE 'low'
    END AS customer_segments
FROM customer_analysis
)
,segment_distribution AS
(
SELECT customer_segments, COUNT(*) AS total_customers
FROM customer_frequency_analysis
GROUP BY customer_segments
)
SELECT 
customer_segments,
total_customers,
ROUND(
	total_customers / SUM(total_customers) OVER()*100,
    2
    ) AS customer_percentage
FROM segment_distribution
ORDER BY total_customers DESC;

-- 25. Which categories have high revenue contribution but low available stock?

WITH product_analysis AS
(
SELECT
p.product_id,
p.Category_ID,
p.Price,
p.Stock,
COALESCE(SUM(oi.quantity), 0) AS total_quantity,
COALESCE(SUM(p.Price * oi.quantity), 0) AS total_revenue
FROM products p
LEFT JOIN order_items oi
ON p.product_id = oi.product_id
GROUP BY
p.product_id,
p.Category_ID,
p.Price,
p.Stock
),
total_revenue_stock AS
(
SELECT
c.category_name,
c.category_id,
ROUND(SUM(pa.total_revenue), 2) AS total_revenue,
SUM(pa.Stock) AS available_stock
FROM product_analysis pa
JOIN category c
ON c.category_id = pa.Category_ID
GROUP BY
c.category_name,
c.category_id
),
category_metrics AS
(
SELECT
category_name,
category_id,
total_revenue,
available_stock,
ROUND(
	total_revenue * 100.0 /NULLIF(SUM(total_revenue) OVER (), 0),
	2) AS revenue_contribution,
AVG(total_revenue) OVER () AS avg_category_revenue,
AVG(available_stock) OVER () AS avg_category_stock
FROM total_revenue_stock
)
SELECT
category_name,
category_id,
total_revenue,
available_stock,
revenue_contribution,
CASE WHEN total_revenue > avg_category_revenue AND available_stock < avg_category_stock
	THEN 'High Revenue - Low Stock'
    ELSE 'Other Categories'
    END AS category_contribution
FROM category_metrics
ORDER BY revenue_contribution DESC;

-- 26. What percentage of orders are cancelled,refunded or returned in each state?

SELECT    
c.state,
COUNT(o.order_id) AS total_orders,
SUM(CASE WHEN o.order_status IN ('Cancelled', 'Returned', 'Refunded') THEN 1
	ELSE 0
	END) AS cancelled_returned_orders,
ROUND(
	SUM(CASE WHEN o.order_status IN ('Cancelled', 'Returned', 'Refunded') THEN 1
    ELSE 0
    END
	) * 100.0 / NULLIF(COUNT(o.order_id), 0),
	2 ) AS cancellation_return_rate
FROM customers c
JOIN orders o
ON c.customer_id = o.customer_id
GROUP BY c.state
ORDER BY cancellation_return_rate DESC;

-- 27. How does revenue from repeat customers compare with revenue from one-time customers?

WITH customer_analysis AS
(
SELECT
customer_id,
COUNT(order_id) AS total_orders,
SUM(order_total) AS total_revenue
FROM orders
WHERE order_status = 'Delivered'
GROUP BY customer_id
),
customer_segments AS
(
SELECT
customer_id,
total_orders,
total_revenue,
CASE WHEN total_orders >= 2 THEN 'Repeat Customer'
     WHEN total_orders = 1 THEN 'One-Time Customer'
     END AS customer_type
FROM customer_analysis
)
SELECT
customer_type,
COUNT(customer_id) AS total_customers,
SUM(total_orders) AS total_orders,
ROUND(SUM(total_revenue), 2) AS total_revenue
FROM customer_segments
GROUP BY customer_type
ORDER BY total_revenue DESC;

-- 28. Which months show seasonal peaks, and how does each month's revenue compare 
-- with the same month in the previous year, if the data covers multiple years?

WITH monthly_revenue AS
(
SELECT
YEAR(order_date) AS year_number,
MONTH(order_date) AS month_number,
MONTHNAME(order_date) AS month_name,
SUM(order_total) AS total_revenue
FROM orders
WHERE order_status = 'Delivered'
GROUP BY
YEAR(order_date),
MONTH(order_date),
MONTHNAME(order_date)
),
yearly_comparison AS
(
SELECT
year_number,
month_number,
month_name,
total_revenue,
LAG(total_revenue) OVER(PARTITION BY month_number ORDER BY year_number) AS previous_year_revenue
FROM monthly_revenue
)
SELECT
year_number,
month_number,
month_name,
ROUND(total_revenue, 2) AS total_revenue,
ROUND(previous_year_revenue, 2) AS previous_year_revenue,
ROUND(
	(total_revenue - previous_year_revenue)
	* 100.0 / NULLIF(previous_year_revenue, 0),
	2) AS yearoveryear_growth_percentage,
CASE WHEN total_revenue > previous_year_revenue
	THEN 'Revenue Increased'
    WHEN total_revenue < previous_year_revenue
	THEN 'Revenue Decreased'
	ELSE 'No Change'
    END AS revenue_trend
FROM yearly_comparison
ORDER BY
    year_number,
    month_number;
    
-- Concepts covered: Multiple CTEs, window functions (SUM() OVER, LAG, DENSE_RANK with PARTITION BY), cumulative totals, 
-- month-over-month and year-over-year growth, customer segmentation, churn analysis, CASE WHEN, date functions (DATEDIFF, YEAR, MONTH, MONTHNAME), NULLIF.
    
  